{
  "student_academic_profile": {
    "profile_type": "academic",
    "courses": [
      {
        "course_code": "MAS291",
        "metadata": {
          "syllabus_name": "Statistics & Probability_Xác suất thống kê",
          "course_name_english": "",
          "subject_code": "MAS291",
          "description": "Upon finishing the course, students must acquire:\n1. the following knowledge:(ABET a1)\n• The fundamental principles of probability and their applications\n• The frequently used probability distributions.\n• The basics of descriptive statistics\n• The inferences of statistics: parameter estimations, hypothesis testing, regressions & correlations.\n2. the following skills: (ABET a2)\n• Recognize simple statistical models and applied them to solve engineering problems.\n• Use at least one statistical software (Excel, Maxima) for problem solving.\n• Self-study skill. (ABET i)",
          "tools": "- Internet\n- Computerized tools (for example Excel and DDXL add-ons) (CT)"
        },
        "clos": [
          {
            "clo": "CLO1",
            "description": "Discuss the roles of statistics in engineering through statistical thinking, the engineering method, and engineering data collection. Explain statistical inference reasoning and distinguish mechanistic models from empirical models, statistics from parameters, and samples from populations in the context of probability and probability models.",
            "score": 9.34,
            "achievement": "excellent"
          },
          {
            "clo": "CLO2",
            "description": "Identify sample spaces, events, and random variables, distinguishing continuous and discrete cases. Use interpretations of probability, event operations, addition rules, conditional probability, multiplication and total probability rules, independence, and Bayes' theorem to calculate event probabilities.",
            "score": 9.34,
            "achievement": "excellent"
          },
          {
            "clo": "CLO3",
            "description": "Describe probability distributions for discrete random variables and calculate probabilities, means, and variances, including probability mass functions, cumulative distribution functions, discrete uniform, binomial, geometric, negative binomial, hypergeometric, Poisson distributions.",
            "score": 9.34,
            "achievement": "excellent"
          },
          {
            "clo": "CLO4",
            "description": "Describe probability distributions for continuous random variables and calculate means, variances, and probabilities using probability density functions and cumulative distribution functions, including continuous uniform, normal, and exponential distributions, standardization of normal distributions, and normal approximations to binomial, Poisson distributions.",
            "score": 9.15,
            "achievement": "excellent"
          },
          {
            "clo": "CLO5",
            "description": "Describe data using numerical summaries and visual displays, including descriptive statistics, stem-and-leaf diagrams, frequency distributions, histograms, box plots, quartiles, outlier identification, and time sequence plots.",
            "score": 9.15,
            "achievement": "excellent"
          },
          {
            "clo": "CLO6",
            "description": "Discuss sampling distributions and point estimation, then use the Central Limit Theorem to analyze sampling distributions of means.",
            "score": 9.15,
            "achievement": "excellent"
          },
          {
            "clo": "CLO7",
            "description": "Construct and interpret confidence intervals for population parameters and differences between population parameters, including intervals for means of normal distributions with known or unknown variance, large-sample intervals for population proportions, inference on differences between two means, and inference on differences between two proportions.",
            "score": 9.43,
            "achievement": "excellent"
          },
          {
            "clo": "CLO8",
            "description": "Verify claims about population parameters and differences between population parameters using hypothesis testing, including formulating hypotheses, identifying critical values and test statistics, computing p-values, recognizing testing errors, and conducting tests for single means, single proportions, differences between two means, and differences between two proportions.",
            "score": 9.43,
            "achievement": "excellent"
          },
          {
            "clo": "CLO9",
            "description": "Construct a simple linear regression model and use it for prediction and interpretation, including empirical models, least-squares estimation, sums of squares, regression equations, correlation coefficients, properties of least-squares estimators, and hypothesis tests for significance in simple linear regression.",
            "score": 9.43,
            "achievement": "excellent"
          }
        ]
      }
    ]
  }
}

